import re
import os
from abc import abstractmethod
from collections import defaultdict
from taf.ul.ettf.events.comparator import On
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.log_analysis.event import SyslogCollected
from taf.ul.ettf.log_analysis.reporter import LogToConsoleAndHtml, PrettyHtmlReporter, LogToFile
from taf.ul.ettf.logger.logger import custom_logger


logger = custom_logger("LogAnalyzer")


class AnalyzedResult(object):
    def __init__(self, analyzed_path, trigger):
        self._data = defaultdict(list)
        self._analyzed_path = analyzed_path
        self._trigger = trigger
        self._anything_to_report = False

    def add_line(self, line, group='default'):
        self._anything_to_report = True
        self._data[group].append(line)

    @property
    def data(self):
        return self._data

    @property
    def analyzed_path(self):
        return self._analyzed_path

    @property
    def trigger(self):
        return self._trigger

    @property
    def anything_to_report(self):
        return self._anything_to_report


class AnalyzedResults(list):
    @property
    def anything_to_report(self):
        return any(ar.anything_to_report for ar in self)


class LogAnalyzer(object):

    def __init__(self, event_type):
        self._event_type = event_type
        self._reporters = []

    def __call__(self):
        Notifier().register(self.analyse, On(self._event_type))

    def with_reporter(self, reporter):
        self._reporters.append(reporter)
        return self

    def analyse(self):
        analyzed_result = self._analyze(Notifier().active_event.paths)
        self.push(analyzed_result)

    @abstractmethod
    def _analyze(self, paths):
        pass

    def push(self, analyzed_result):
        self._supply_default_reporters_if_none_set()
        for reporter in self._reporters:
            reporter(analyzed_result)

    def _supply_default_reporters_if_none_set(self):
        if not self._reporters:
            self._reporters.append(LogToConsoleAndHtml())
            self._reporters.append(LogToFile())
            self._reporters.append(PrettyHtmlReporter())


class SyslogAnalyzer(LogAnalyzer):
    def __init__(self, event_type=SyslogCollected):
        super(SyslogAnalyzer, self).__init__(event_type)
        self._regexes = [self._get_err_pid_regex(), self._get_fatal_regex()]

    def with_pattern(self, regex):
        self._regexes.append(regex)
        return self

    def _analyze(self, paths):
        try:
            logger.debug('SyslogAnalyzer triggered')
            return self._analyze_files(paths)
        finally:
            logger.debug('SyslogAnalyzer finished')

    def _analyze_files(self, paths):
        results = AnalyzedResults()
        for p in paths:
            if os.path.isfile(p):
                results.append(self._analyze_file(p))
            else:
                logger.info('Logging path: {} is not an existing file, skipped for analyzing.'.format(p))
        return results

    def _analyze_file(self, path):
        ar = AnalyzedResult(path, Notifier().active_event)
        with open(path) as f:
            for line in f:
                for pattern in self._regexes:
                    if re.match(pattern, line):
                        ar.add_line(line, pattern)
        return ar

    @staticmethod
    def _get_err_pid_regex():
        return r'.*ERR.*pid.*'

    @staticmethod
    def _get_fatal_regex():
        return r'.*\*\*\sFATAL.*'
